# Focus on the two specialties we care about: cardiology and general practice
target_specialties = ['cardiology', 'general practice']

# Get all entities that have at least one of these specialties
entity_specialty_map = {}
for idx, row in candidates_df.iterrows():
    entity = row['entity']
    specialty = row['specialty']
    if specialty in target_specialties:
        if entity not in entity_specialty_map:
            entity_specialty_map[entity] = set()
        entity_specialty_map[entity].add(specialty)

# Find entities with BOTH specialties
entities_with_both = {e: specs for e, specs in entity_specialty_map.items() if len(specs) == 2}
print(f"Entities with BOTH cardiology and general practice: {len(entities_with_both)}")
for e in sorted(entities_with_both.keys()):
    print(f"  {e}")
